// CertificationsPage.jsx
import React, { useState, useEffect, useRef } from 'react';
import { Helmet } from 'react-helmet-async';
import * as d3 from 'd3';
import { Download } from 'lucide-react';
import certificationsData from '../data/Certifications.js';

const D3_COLORS = {
  border:      '#334155',
  purple:      '#8b5cf6',
  blue:        '#60a5fa',
  textPrimary: '#ffffff',
};

const categories = [
  { name: 'Security',     color: '#f87171' },
  { name: 'Cloud',        color: '#38bdf8' },
  { name: 'Development',  color: '#8b5cf6' },
  { name: 'DevOps',       color: '#34d399' },
  { name: 'Data',         color: '#fbbf24' },
  { name: 'Architecture', color: '#a78bfa' },
  { name: 'Other',        color: '#94a3b8' },
];

export default function CertificationsPage() {
  const [selectedCert, setSelectedCert]         = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const svgRef = useRef();

  const categoryGroups = {};
  certificationsData.forEach(cert => {
    if (!categoryGroups[cert.category]) categoryGroups[cert.category] = [];
    categoryGroups[cert.category].push(cert);
  });

  const getDisplayedCerts = () => {
    if (selectedCert)     return [selectedCert];
    if (selectedCategory) return categoryGroups[selectedCategory] || [];
    return certificationsData;
  };

  const displayedCerts = getDisplayedCerts();

  // ── D3 setup (runs once) ──────────────────────────────────────────────────
  useEffect(() => {
    if (!svgRef.current) return;
    const width  = svgRef.current.clientWidth;
    const height = 600;

    const nodes = [
      { id: 'Hubert', label: 'Hubert', type: 'center', category: 'center' },
      ...certificationsData.map(cert => ({
        id: cert.id, label: cert.name, type: 'cert', category: cert.category,
      })),
    ];

    const links = [];
    certificationsData.forEach(cert => {
      links.push({ source: 'Hubert', target: cert.id });
      cert.connections.forEach(conn => {
        if (certificationsData.find(c => c.id === conn))
          links.push({ source: cert.id, target: conn });
      });
    });

    const uniqueLinks = [];
    const linkSet = new Set();
    links.forEach(link => {
      const key = [link.source, link.target].sort().join('-');
      if (!linkSet.has(key)) { uniqueLinks.push(link); linkSet.add(key); }
    });

    const simulation = d3
      .forceSimulation(nodes)
      .force('link',      d3.forceLink(uniqueLinks).id(d => d.id).distance(80))
      .force('charge',    d3.forceManyBody().strength(-300))
      .force('center',    d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(40));

    const svg = d3.select(svgRef.current);
    svg.attr('class', 'network-svg');
    svg.selectAll('*').remove();

    const g = svg
      .attr('width', width)
      .attr('height', height)
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('role', 'img')
      .attr('aria-label', 'Network diagram showing how my certifications connect and relate to each other')
      .append('g');

    const link = g
      .selectAll('line')
      .data(uniqueLinks)
      .enter()
      .append('line')
      .attr('stroke', D3_COLORS.border)
      .attr('stroke-width', 2)
      .attr('opacity', 0.4);

    const node = g
      .selectAll('g.node')
      .data(nodes)
      .enter()
      .append('g')
      .attr('class', 'node')
      .call(
        d3.drag()
          .on('start', (e, d) => { if (!e.active) simulation.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; })
          .on('drag',  (e, d) => { d.fx = e.x; d.fy = e.y; })
          .on('end',   (e, d) => { if (!e.active) simulation.alphaTarget(0); d.fx = null; d.fy = null; })
      );

    node
      .append('circle')
      .attr('r', d => (d.type === 'center' ? 40 : 25))
      .attr('fill', d => {
        if (d.type === 'center') return D3_COLORS.purple;
        const cat = categories.find(c => c.name === d.category);
        return cat ? cat.color : D3_COLORS.blue;
      })
      .attr('opacity', 0.9)
      .attr('stroke', D3_COLORS.textPrimary)
      .attr('stroke-width', 2)
      .style('cursor', 'pointer')
      .on('click', (e, d) => {
        if (d.type !== 'center') {
          const cert = certificationsData.find(c => c.id === d.id);
          setSelectedCert(cert);
          setSelectedCategory(null);
        }
      })
      .on('mouseover', (e, d) => {
        link.attr('stroke', l =>
          (l.source.id === d.id || l.target.id === d.id) ? D3_COLORS.purple : D3_COLORS.border
        );
      })
      .on('mouseout', () => link.attr('stroke', D3_COLORS.border));

    node
      .append('text')
      .text(d => d.label)
      .attr('text-anchor', 'middle')
      .attr('dy', '0.3em')
      .attr('fill', D3_COLORS.textPrimary)
      .attr('font-size', '12px')
      .attr('font-weight', 'bold')
      .attr('pointer-events', 'none');

    simulation.on('tick', () => {
      link
        .attr('x1', d => d.source.x).attr('y1', d => d.source.y)
        .attr('x2', d => d.target.x).attr('y2', d => d.target.y);
      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    return () => simulation.stop();
  }, []);

  // ── D3 filter (runs when selection changes) ───────────────────────────────
  useEffect(() => {
    if (!svgRef.current) return;
    const svg = d3.select(svgRef.current);

    if (!selectedCategory && !selectedCert) {
      svg.selectAll('g.node').transition().duration(300).attr('opacity', 1);
      svg.selectAll('line').transition().duration(300).attr('opacity', 0.4);
      return;
    }

    let relevantIds;

    if (selectedCert) {
      relevantIds = new Set(['Hubert', selectedCert.id, ...selectedCert.connections]);
    } else {
      const catCerts = certificationsData.filter(c => c.category === selectedCategory);
      relevantIds = new Set(['Hubert', ...catCerts.map(c => c.id)]);
      catCerts.forEach(c => c.connections.forEach(conn => relevantIds.add(conn)));
    }

    svg.selectAll('g.node')
      .transition().duration(300)
      .attr('opacity', d => relevantIds.has(d.id) ? 1 : 0.08);

    svg.selectAll('line')
      .transition().duration(300)
      .attr('opacity', l => {
        const src = l.source?.id ?? l.source;
        const tgt = l.target?.id ?? l.target;
        return (relevantIds.has(src) && relevantIds.has(tgt)) ? 0.6 : 0.03;
      });
  }, [selectedCategory, selectedCert]);

  const handleCategoryClick = (categoryName) => {
    setSelectedCategory(selectedCategory === categoryName ? null : categoryName);
    setSelectedCert(null);
  };

  const handleClearFilters = () => {
    setSelectedCert(null);
    setSelectedCategory(null);
  };

  return (
    <div className="certifications-container">
      <Helmet>
        <title>Certifications | Hubert de Tournay</title>
        <meta
          name="description"
          content="Cybersecurity, cloud, and IT certifications earned by Hubert de Tournay, including ANSSI, Fortinet, and CISSP-oriented training."
        />
        <link rel="canonical" href="https://www.de-tournay.fr/certifications" />
      </Helmet>

      <section className="hero-section">
        <h1 className="hero-title">My Certifications</h1>
        <p className="introduction">
          A collection of certifications that validate my expertise across various domains.
          Each certification represents dedicated learning and hands-on experience in its respective field.
          Click on any card to view or download the certification document.
        </p>
      </section>

      <section className="category-section">
        <h2 className="section-title">Certification Categories</h2>
        <div className="category-grid">
          {categories.map(cat => {
            const certCount = certificationsData.filter(c => c.category === cat.name).length;
            const isActive  = selectedCategory === cat.name;
            return (
              <div
                key={cat.name}
                className={`category-card ${isActive ? 'active' : ''}`}
                onClick={() => handleCategoryClick(cat.name)}
              >
                <div className="category-dot" style={{ backgroundColor: cat.color }} />
                <h3 className="category-name">{cat.name}</h3>
                <p className="skill-count">{certCount} certification{certCount !== 1 ? 's' : ''}</p>
              </div>
            );
          })}
        </div>

        {(selectedCert || selectedCategory) && (
          <div className="filter-info">
            <p className="filter-text">
              {selectedCert
                ? `Showing: ${selectedCert.name}`
                : `Showing ${displayedCerts.length} certification(s) from ${selectedCategory}`}
            </p>
            <button onClick={handleClearFilters} className="clear-button">
              Clear Filters
            </button>
          </div>
        )}
      </section>

      <section className="network-section">
        <h2 className="section-title">Certifications Network Map</h2>
        <p className="network-description">
          Interactive map of how my certifications connect and relate. Click on any certification bubble to highlight its connections.
        </p>
        <div className="network-container">
          <svg ref={svgRef} />
        </div>
        <div className="network-legend">
          <p className="legend-title">Click on any certification to explore its connections. Drag to reposition.</p>
          {selectedCert && (
            <div className="selected-cert-info">
              <strong>Selected: {selectedCert.name}</strong>
              <p>
                Connections:{' '}
                {selectedCert.connections
                  .map(id => certificationsData.find(c => c.id === id)?.name)
                  .filter(Boolean)
                  .join(', ') || 'None'}
              </p>
            </div>
          )}
        </div>
      </section>

      <section className="certifications-section">
        <h2 className="section-title">
          {selectedCert
            ? selectedCert.name
            : selectedCategory
            ? `${selectedCategory} Certifications`
            : 'All Certifications'}
        </h2>
        <div className="certifications-grid">
          {displayedCerts.map(cert => (
            <div
              key={cert.id}
              className={`cert-card ${selectedCert?.id === cert.id ? 'active' : ''}`}
              onClick={() => {
                setSelectedCert(cert);
                setSelectedCategory(null);
              }}
            >
              <div className="cert-card-header">
                <div
                  className="category-badge"
                  style={{ backgroundColor: categories.find(c => c.name === cert.category)?.color || '#60a5fa' }}
                >
                  {cert.category}
                </div>
                <span className="cert-date">{cert.obtained}</span>
              </div>

              <a
                href={cert.document}
                download={cert.document}
                className="download-button"
                onClick={e => e.stopPropagation()}
              >
                <div className="document-container">
                  <div className="document-icon">
                    <Download size={48} />
                  </div>
                  <p className="document-name">{cert.name}</p>
                  <p className="document-hint">PDF Certificate</p>
                </div>
              </a>

              <h3 className="cert-name">{cert.name}</h3>
              <p className="cert-summary">{cert.summary}</p>

              {cert.connections.length > 0 && (
                <div className="connections-container">
                  <p className="cert-label">Related Certifications:</p>
                  <div className="connections-tags">
                    {cert.connections.map(connId => {
                      const connCert = certificationsData.find(c => c.id === connId);
                      return (
                        <span key={connId} className="connection-tag">
                          {connCert?.name}
                        </span>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}
